const staticData = $getWorkflowStaticData('global');
const chatId = $json.message.chat.id.toString();
const text = ($json.message.text || '').trim();

if (!staticData.sessions) staticData.sessions = {};
if (!staticData.orderCounter) staticData.orderCounter = 0;
if (!staticData.sessions[chatId]) staticData.sessions[chatId] = { step: 0, data: { products: [] } };

const session = staticData.sessions[chatId];
if (!session.data.products) session.data.products = [];

// ─── LUNAR CALCULATOR ────────────────────────────────────────────────────────
function getMoonData(date) {
  const J2000 = new Date('2000-01-01T12:00:00Z');
  const daysSinceJ2000 = (date - J2000) / 86400000;

  // Moon mean longitude (tropical)
  const L = ((218.3165 + 13.17639648 * daysSinceJ2000) % 360 + 360) % 360;
  const signIndex = Math.floor(L / 30);
  const signs = ['Aries','Tauro','Geminis','Cancer','Leo','Virgo','Libra','Escorpio','Sagitario','Capricornio','Acuario','Piscis'];
  const sign = signs[signIndex];

  // Moon phase (synodic)
  const knownNew = new Date('2000-01-06T18:14:00Z');
  const SYNODIC = 29.530589;
  const daysSinceNew = (date - knownNew) / 86400000;
  const cycle = ((daysSinceNew % SYNODIC) + SYNODIC) % SYNODIC;
  const illumination = Math.round(50 * (1 - Math.cos(2 * Math.PI * cycle / SYNODIC)));

  let phase;
  if (cycle < 1.85) phase = 'Luna Nueva';
  else if (cycle < 7.38) phase = 'Luna Creciente';
  else if (cycle < 9.22) phase = 'Cuarto Creciente';
  else if (cycle < 14.77) phase = 'Gibosa Creciente';
  else if (cycle < 16.61) phase = 'Luna Llena';
  else if (cycle < 22.15) phase = 'Gibosa Menguante';
  else if (cycle < 23.99) phase = 'Cuarto Menguante';
  else phase = 'Luna Menguante';

  const bioType = { Aries:'fruto', Tauro:'raiz', Geminis:'flor', Cancer:'hoja',
    Leo:'fruto', Virgo:'raiz', Libra:'flor', Escorpio:'hoja',
    Sagitario:'fruto', Capricornio:'raiz', Acuario:'flor', Piscis:'hoja' };

  return { sign, phase, illumination, type: bioType[sign], cycleDay: Math.round(cycle) };
}

function buildBioTip(date) {
  const m = getMoonData(date);
  const dateStr = date.toLocaleDateString('es-AR', { weekday:'long', day:'numeric', month:'long', year:'numeric' });

  const typeInfo = {
    raiz:  { titulo:'DIA DE RAICES',  cultivos:'zanahorias, remolachas, cebollas, ajos, papas, puerros, rabanos',  consejo:'Cosechar, trasplantar y trabajar raices, tuberculos y bulbos. La savia baja hacia las raices.' },
    hoja:  { titulo:'DIA DE HOJAS',   cultivos:'lechugas, acelgas, espinacas, kale, rucula, perejil, cilantro',    consejo:'Regar, fertilizar y cosechar hojas. La savia sube hacia el follaje. Bueno para plantar y trasplantar verduras de hoja.' },
    fruto: { titulo:'DIA DE FRUTOS',  cultivos:'tomates, pimientos, zapallo, pepinos, porotos, guisantes, maiz',    consejo:'Cosechar frutos y semillas. Excelente para secar y guardar semillas. La energia se concentra en los frutos.' },
    flor:  { titulo:'DIA DE FLORES',  cultivos:'flores, aromaticas, lavanda, manzanilla, calendula, albahaca',      consejo:'Trabajar flores y aromaticas, cortar flores para ramos, podar plantas en flor. Favorece el aroma y la belleza.' }
  };

  const phaseInfo = {
    'Luna Nueva':        'LUNA NUEVA: Energia baja. Ideal para preparar canteros y compostar. Evitar sembrar.',
    'Luna Creciente':    'LUNA CRECIENTE: Energia ascendente. Buen momento para sembrar plantas de hoja y flor.',
    'Cuarto Creciente':  'CUARTO CRECIENTE: Energia fuerte. Muy bueno para sembrar y transplantar.',
    'Gibosa Creciente':  'GIBOSA CRECIENTE: Maxima energia ascendente. Excelente para sembrar y fertilizar con biofertilizantes.',
    'Luna Llena':        'LUNA LLENA: Maxima energia. Ideal para cosechar, resembrar y hacer preparados biodinamicos.',
    'Gibosa Menguante':  'GIBOSA MENGUANTE: Energia descendente. Bueno para podar, conservar y hacer mermeladas.',
    'Cuarto Menguante':  'CUARTO MENGUANTE: Energia menguante. Bueno para labrar la tierra, hacer compost y desmalezar.',
    'Luna Menguante':    'LUNA MENGUANTE: Energia en reposo. Ideal para barbecho, limpieza y descanso del huerto.'
  };

  const ti = typeInfo[m.type];
  return '🌱 Calendario Biodinamico\n' + dateStr + '\n\n' +
    'Luna en ' + m.sign + ' (' + m.phase + ', ' + m.illumination + '% iluminada)\n' +
    'Dia ' + m.cycleDay + ' del ciclo lunar\n\n' +
    ti.titulo + '\n' +
    'Cultivos favorables: ' + ti.cultivos + '\n\n' +
    'Que hacer hoy: ' + ti.consejo + '\n\n' +
    phaseInfo[m.phase] + '\n\n' +
    'Escribi 1 para hacer un pedido o 4 para fichas de plantas.';
}
// ─────────────────────────────────────────────────────────────────────────────

const MENU = 'Bienvenido a El Huerto de Lucas!\n\nQue queres hacer?\n\n1. Tienda online (hacer un pedido)\n2. Mis redes y contacto\n3. Consejo biodinamico de hoy\n4. Fichas de plantas';

let response = '';
let checkStock = false;
let productSlug = '';
let productName = '';
let sendToLucas = false;
let sendQR = false;
let notifyPayment = false;
let orderSummary = '';
let paymentSummary = '';
let sheetData = {};
let routeTo = 'order';

// ─── STEP 0: MAIN MENU ───────────────────────────────────────────────────────
if (session.step === 0) {

  // Awaiting plant question (option 4 sub-flow)
  if (session.menuMode === 'fichas') {
    session.menuMode = null;
    return [{ json: { chatId, routeTo: 'ai',
      userMessage: 'El usuario pregunta sobre como cultivar: ' + text + '. Respondé con ficha practica de cultivo agroecologico: epocas de siembra (indicar meses para Buenos Aires/zona templada), distancias entre plantas, profundidad de siembra, dias a cosecha, variedades recomendadas, riego y tips de manejo agroecologico. Si pregunta algo que no es una planta, indicale que escriba el nombre de un cultivo.',
      response: '', checkStock: false, sendToLucas: false, sendQR: false, notifyPayment: false, orderSummary: '', paymentSummary: '', sheetData: {} } }];
  }

  if (text === '1') {
    session.step = 1;
    response = 'Genial! Para hacer tu pedido necesito algunos datos.\n\nCual es tu nombre?';

  } else if (text === '2') {
    response = 'El Huerto de Lucas\n\nInstagram: @elhuertodelucas\nWhatsApp: +54 11 2532-8861\nDireccion: Los Sauces 264, General Pinto, Buenos Aires\nWeb: elhuertodelucas.com.ar\n\nEscribi 1, 3 o 4 para otras opciones.';

  } else if (text === '3') {
    response = buildBioTip(new Date());

  } else if (text === '4') {
    session.menuMode = 'fichas';
    response = 'Fichas de plantas!\n\nQue planta o cultivo queres consultar?\n(Ejemplo: acelga, tomate, zanahoria, lechuga...)';

  } else {
    response = MENU;
  }

  return [{ json: { chatId, routeTo, userMessage: text, response, checkStock: false, sendToLucas: false, sendQR: false, notifyPayment: false, orderSummary: '', paymentSummary: '', sheetData: {} } }];
}

// ─── STEPS 1-7: ORDER FLOW ───────────────────────────────────────────────────

const productMap = {
  'acelga': { name: 'Acelga', slug: 'hortalizas/de-hojas/acelga-agroecologica-mix-variedades-atado' },
  'rucula': { name: 'Rucula', slug: 'hortalizas/de-hojas/rucula-agroecologica-atado' },
  'kale': { name: 'Kale', slug: 'hortalizas/de-hojas/kale-agroecologico-atado' },
  'huevos': { name: 'Huevos de Campo', slug: 'granja/avicola/huevos-de-campo-docena' },
  'puerro': { name: 'Puerro', slug: 'hortalizas/de-raices/puerro-agroecologico-atado' },
  'albahaca': { name: 'Albahaca', slug: 'aromaticas/atados-frescos/albahaca-agroecologica-atado' },
  'ciboulette': { name: 'Ciboulette', slug: 'aromaticas/atados-frescos/cibullete-agroecologico-atado' },
  'cibullete': { name: 'Ciboulette', slug: 'aromaticas/atados-frescos/cibullete-agroecologico-atado' },
  'oregano': { name: 'Oregano', slug: 'aromaticas/oregano-en-hojas-deshidratado-30gr' },
  'laurel': { name: 'Laurel', slug: 'aromaticas/atados-frescos/laurel-agroecologico-fresco-atado' },
  'achicoria': { name: 'Achicoria', slug: 'hortalizas/de-hojas/achicoria-agroecologica-atado' },
  'cebolla': { name: 'Cebolla de Verdeo', slug: 'hortalizas/de-hojas/cebolla-de-verdeo-agroecologica-atado' },
  'ensalada': { name: 'Hojas de Ensalada', slug: 'bolsones-y-mezclum/mezclum/hojas-ensalada-350gr' },
};

const prices = {
  'Acelga': 2800, 'Rucula': 2000, 'Kale': 1800, 'Huevos de Campo': 5000,
  'Puerro': 2500, 'Albahaca': 1600, 'Ciboulette': 1500, 'Oregano': 1800,
  'Laurel': 1000, 'Achicoria': 1000, 'Cebolla de Verdeo': 1800, 'Hojas de Ensalada': 4000,
};

function fmt(n) { return n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.'); }

function calcTotal(products) {
  let total = 0;
  for (const item of products) {
    const match = item.match(/^(\d+)\s*x\s*(.+)$/i);
    if (match) total += parseInt(match[1]) * (prices[match[2].trim()] || 0);
  }
  return total;
}

if (session.step === 1) {
  session.data.name = text;
  session.step = 2;
  response = 'Gracias ' + text + '! Que producto queres agregar?\n(Escribi el nombre, o listo cuando termines)';

} else if (session.step === 2) {
  const lower = text.toLowerCase();
  if (session.data.awaitingQuantity) {
    const pName = session.data.pendingProductName || 'Producto';
    session.data.products.push(text + ' x ' + pName);
    delete session.data.awaitingQuantity;
    delete session.data.pendingProductName;
    delete session.data.pendingProduct;
    response = text + ' x ' + pName + ' agregado!\nEscribi otro producto o listo para terminar.';
  } else if (lower === 'listo') {
    if (session.data.products.length === 0) {
      response = 'No agregaste ningun producto todavia. Escribi el nombre de un producto para empezar.';
    } else {
      const total = calcTotal(session.data.products);
      const discount = Math.min(Math.round(total * 0.4), 4000);
      session.data.total = total;
      session.step = 3;
      response = 'Tu pedido:\n- ' + session.data.products.join('\n- ') +
        '\n\nTotal: $' + fmt(total) + ' (con Cuenta DNI: $' + fmt(total - discount) + ')' +
        '\n\nComo queres recibir tu pedido?\n1. Envio a domicilio (sin costo, General Pinto)\n2. Retiro en el huerto (Sabados 15 a 18hs)\n3. Retiro en feria (Sabados cada 15 dias, 10 a 12:30hs)';
    }
  } else {
    let found = null;
    for (const [key, val] of Object.entries(productMap)) {
      if (lower.includes(key)) { found = val; break; }
    }
    if (found) {
      checkStock = true;
      productSlug = found.slug;
      productName = found.name;
      session.data.pendingProduct = text;
      session.data.pendingProductName = found.name;
    } else {
      response = 'No encontre ese producto.\nEscribi alguno de estos: Acelga, Kale, Puerro, Rucula, Huevos, Albahaca, Ciboulette, Oregano, Laurel, Achicoria, Cebolla, Ensalada.';
    }
  }

} else if (session.step === 3) {
  if (text === '1') {
    session.data.delivery = 'Envio a domicilio';
    session.step = 4;
    response = 'Envio a domicilio seleccionado.\nCual es tu direccion en General Pinto?';
  } else if (text === '2') {
    session.data.delivery = 'Retiro en el huerto';
    session.data.address = 'Retiro en el huerto (Sabados 15 a 18hs)';
    session.step = 5;
    response = 'Retiro en el huerto seleccionado (Sabados de 15 a 18hs).\nCual es tu numero de telefono?';
  } else if (text === '3') {
    session.data.delivery = 'Retiro en feria';
    session.data.address = 'Retiro en feria (Sabados cada 15 dias, 10 a 12:30hs)';
    session.step = 5;
    response = 'Retiro en feria seleccionado (Sabados cada 15 dias, de 10 a 12:30hs).\nCual es tu numero de telefono?';
  } else {
    response = 'Escribi 1, 2 o 3 para elegir:\n1. Envio a domicilio (sin costo, General Pinto)\n2. Retiro en el huerto (Sabados 15 a 18hs)\n3. Retiro en feria (Sabados c/15 dias, 10 a 12:30hs)';
  }

} else if (session.step === 4) {
  session.data.address = text;
  session.step = 5;
  response = 'Cual es tu numero de telefono?';

} else if (session.step === 5) {
  session.data.phone = text;
  staticData.orderCounter++;
  const orderNum = 'PED-' + String(staticData.orderCounter).padStart(4, '0');
  const ahora = new Date();
  const fecha = ahora.toLocaleDateString('es-AR') + ' ' + ahora.toLocaleTimeString('es-AR');
  const totalStr = '$' + fmt(session.data.total || 0);
  sheetData = {
    Pedido: orderNum,
    Fecha: fecha,
    Nombre: session.data.name,
    Productos: session.data.products.join(', '),
    Total: totalStr,
    Entrega: session.data.delivery || '',
    Direccion: session.data.address || '',
    Telefono: text,
    Pago: 'Pendiente'
  };
  orderSummary = orderNum + ' - NUEVO PEDIDO\n\nNombre: ' + session.data.name +
    '\nProductos:\n- ' + session.data.products.join('\n- ') +
    '\nTotal: ' + totalStr +
    '\nEntrega: ' + (session.data.delivery || '') +
    '\nDireccion: ' + (session.data.address || '') +
    '\nTelefono: ' + text +
    '\nPago: PENDIENTE';
  response = 'Pedido ' + orderNum + ' registrado!\n\nComo vas a abonar?\n1. Efectivo (al momento de la entrega/retiro)\n2. Transferencia bancaria';
  sendToLucas = true;
  session.step = 6;

} else if (session.step === 6) {
  if (text === '1') {
    response = 'Pago en efectivo seleccionado. Te contactamos para coordinar. Gracias por elegirnos!';
    staticData.sessions[chatId] = { step: 0, data: { products: [] } };
  } else if (text === '2') {
    response = 'Para transferir usa el alias: lucaspirizmp\nTe mandamos el QR a continuacion.\n\nCuando realices el pago, manda el comprobante por aca.';
    sendQR = true;
    session.step = 7;
  } else {
    response = 'Escribi 1 o 2:\n1. Efectivo (al momento de entrega/retiro)\n2. Transferencia bancaria';
  }

} else if (session.step === 7) {
  const nombre = session.data.name || 'cliente';
  response = 'Comprobante recibido! Tu pago esta confirmado. El pedido queda pendiente de envio. Gracias!';
  paymentSummary = 'PAGO RECIBIDO\n\nCliente: ' + nombre + '\nComprobante de transferencia recibido.\nPedido listo para procesar.';
  notifyPayment = true;
  staticData.sessions[chatId] = { step: 0, data: { products: [] } };
}

return [{ json: { chatId, response, routeTo, checkStock, productSlug, productName, sendToLucas, sendQR, notifyPayment, orderSummary, paymentSummary, sheetData } }];

const chatId = $('Code Main').item.json.chatId;
const response = $json.output;
return [{ json: { chatId, response } }];

const staticData = $getWorkflowStaticData('global');
const mainData = $('Code Main').item.json;
const chatId = mainData.chatId;
const productName = mainData.productName;
const session = staticData.sessions[chatId];
const html = $json.data || '';
const isOutOfStock = html.includes('product-tag--sin-stock');
let response = '';
if (isOutOfStock) {
  delete session.data.pendingProduct;
  delete session.data.pendingProductName;
  response = 'Lo siento, ' + productName + ' no esta disponible ahora.\nEscribi otro producto o listo para continuar.';
} else {
  session.data.awaitingQuantity = true;
  response = productName + ' disponible! Cuantos atados/unidades queres?';
}
return [{ json: { chatId, response } }];

const d = $json.sheetData;
return [{ json: {
  Pedido: d.Pedido,
  Fecha: d.Fecha,
  Nombre: d.Nombre,
  Productos: d.Productos,
  Total: d.Total,
  Entrega: d.Entrega,
  Direccion: d.Direccion,
  Telefono: d.Telefono,
  Pago: d.Pago || 'Pendiente'
} }];
